from typing import Optional
from google.adk.agents import LlmAgent

def issue_refund(order_id: str, amount: int) -> dict:
    """주문 번호와 금액으로 환불을 처리한다."""
    return {"status": "환불 완료", "amount": amount}

def check_refund_limit(tool, args, tool_context) -> Optional[dict]:
    if tool.name == "issue_refund" and args.get("amount", 0) > 100:
        return {"status": "승인 필요", "reason": "금액 한도 초과"}
    return None  # 한도 이내면 도구가 그대로 실행된다

def log_refund_result(tool, args, tool_context, tool_response) -> Optional[dict]:
    print(f"[{tool.name}] 입력={args} 결과={tool_response}")
    return None  # 결과를 그대로 둔다

support_agent = LlmAgent(
    name="support_agent",
    model="gemini-2.5-flash",
    instruction="환불 문의를 처리한다.",
    tools=[issue_refund],
    before_tool_callback=check_refund_limit,
    after_tool_callback=log_refund_result,
)
